<script setup lang="ts">
import {computed,ref} from 'vue';
import VIcon from '../icons/VIcon.vue';
interface Item {id?:string;label?:string;description?:string;price?:number;quantity?:number;icon?:string;date?:string;status?:string}
const props=withDefaults(defineProps<{kind:string;title?:string;description?:string;items?:Item[];amount?:number;currency?:string;total?:number;discount?:number;tax?:number;percentage?:number;plan?:string;status?:string;code?:string;date?:string;value?:number;modelValue?:string|number|string[];image?:string}>(),{currency:'USD',items:()=>[],discount:0,tax:0});
const emit=defineEmits<{'update:modelValue':[value:string|number|string[]];select:[id:string];action:[id:string]}>();
const selected=ref<string[]>([]);const quantity=ref(2);const promo=ref('SUMMER25');const applied=ref(false);const cycle=ref('year');const method=ref('card');
const defaults:Record<string,string>={VProductCard:'Summer Camp 2026',VProductSelector:'Additional options',VQuantitySelector:'Campers',VDiscountCode:'Discount code',VDiscountBadge:'Special offer',VBillingCycleSelector:'Billing cycle',VPlanComparison:'Compare plans',VCheckoutSteps:'Checkout progress',VPaymentMethodSelector:'Payment methods',VPaymentMethodForm:'Payment details',VSecurePaymentNotice:'Your payment is secure',VPaymentSchedule:'Payment schedule',VCheckoutSummary:'Order summary',VPaymentStatus:'Payment status',VPaymentConfirmation:'Payment successful!',VInvoiceCard:'Invoice #INV-2026-0084',VInvoiceLineItems:'Invoice items',VInvoiceTimeline:'Invoice activity',VReceiptPreview:'Payment receipt',VSubscriptionCard:'Growth plan',VPlanChangeSummary:'Change your plan',VRenewalNotice:'Renews in 14 days',VOverdueNotice:'Payment overdue',VTransactionList:'Recent transactions',VTransactionDetails:'Transaction details',VRefundSummary:'Refund details',VAccountBalance:'Account balance',VFeeBreakdown:'Fee breakdown'};
const name=computed(()=>props.title||defaults[props.kind]||props.kind);
const exampleItems:Item[]=[{id:'session',label:'Session 1',description:'Day Camp',price:500,quantity:1,icon:'tent'},{id:'transport',label:'Transportation',description:'Round trip',price:150,quantity:1,icon:'bus'},{id:'tshirt',label:'Camp T-shirt',description:'Extra merchandise',price:25,quantity:2,icon:'shirt'}];
const rows=computed(()=>props.items.length?props.items:exampleItems);
const money=(n:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:props.currency}).format(n);
const sum=computed(()=>props.amount??props.total??rows.value.reduce((s,r)=>s+(r.price||0)*(r.quantity||1),0));
function choose(id:string){if(selected.value.includes(id))selected.value=selected.value.filter(x=>x!==id);else selected.value=[...selected.value,id];emit('select',id);emit('update:modelValue',selected.value)}
</script>
<template><div class="vx-commerce-widget" :data-kind="kind">
 <template v-if="kind==='VProductCard'"><div class="vx-commerce-product-poster"><img v-if="image" :src="image" alt=""/><VIcon v-else name="mountain" :size="42"/></div><h3>{{name}}</h3><p class="vx-commerce-muted">{{description||'1 week · Ages 8–12'}}</p><strong class="vx-commerce-value">{{money(amount??450)}}</strong><button type="button" class="vx-commerce-primary" @click="emit('action','add')">Add to cart</button></template>
 <template v-else-if="kind==='VProductSelector'"><h3>{{name}}</h3><button v-for="r in rows" :key="r.id" class="vx-commerce-choice" @click="choose(r.id||r.label||'')"><span class="vx-commerce-check">{{selected.includes(r.id||r.label||'')?'✓':''}}</span><span class="vx-commerce-item-icon"><VIcon :name="r.icon||'package'" :size="19"/></span><span class="vx-commerce-flex"><strong>{{r.label}}</strong><small>{{r.description}}</small></span><strong>{{money(r.price||0)}}</strong></button></template>
 <template v-else-if="kind==='VQuantitySelector'"><h3>{{name}}</h3><div class="vx-commerce-stepper"><button @click="quantity=Math.max(1,quantity-1);emit('update:modelValue',quantity)" aria-label="Decrease">−</button><strong>{{quantity}}</strong><button @click="quantity++;emit('update:modelValue',quantity)" aria-label="Increase">+</button></div><p class="vx-commerce-muted">{{money(amount??450)}} each</p><div class="vx-commerce-total"><span>Total</span><strong>{{money(quantity*(amount??450))}}</strong></div></template>
 <template v-else-if="kind==='VDiscountCode'"><h3>{{name}}</h3><div class="vx-commerce-inline"><input v-model="promo" aria-label="Promotion code"/><button type="button" @click="applied=true;emit('action','apply-discount')">Apply</button></div><p v-if="applied" class="vx-commerce-success"><VIcon name="check-circle"/> Discount applied!</p></template>
 <template v-else-if="kind==='VDiscountBadge'"><span class="vx-commerce-sale">{{percentage||20}}% OFF</span><div class="vx-commerce-product-poster"><VIcon name="shopping-bag" :size="48"/></div><h3>{{name}}</h3><s>{{money(50)}}</s> <strong>{{money(40)}}</strong></template>
 <template v-else-if="kind==='VBillingCycleSelector'"><h3>{{name}}</h3><button class="vx-commerce-choice" v-for="c in [{id:'month',label:'Monthly',price:29},{id:'year',label:'Yearly',price:290},{id:'2years',label:'2 Years',price:520}]" :key="c.id" @click="cycle=c.id;emit('update:modelValue',c.id)"><span>{{cycle===c.id?'🔘':'◯'}}</span><span class="vx-commerce-flex"><strong>{{c.label}}</strong></span><strong>{{money(c.price)}}</strong></button></template>
 <template v-else-if="kind==='VPlanComparison'"><h3>{{name}}</h3><table class="vx-commerce-table"><thead><tr><th>Feature</th><th>Starter</th><th>Growth</th></tr></thead><tbody><tr v-for="r in [{label:'Projects',a:'1',b:'Unlimited'},{label:'Reports',a:'—',b:'✓'},{label:'Priority support',a:'—',b:'✓'}]" :key="r.label"><td>{{r.label}}</td><td>{{r.a}}</td><td>{{r.b}}</td></tr></tbody></table></template>
 <template v-else-if="kind==='VCheckoutSteps'||kind==='VInvoiceTimeline'||kind==='VPaymentSchedule'"><h3>{{name}}</h3><ol class="vx-commerce-timeline"><li v-for="(r,i) in (kind==='VCheckoutSteps'?[{label:'Cart',description:'Review your items'},{label:'Details',description:'Your information'},{label:'Payment',description:'Choose a method'},{label:'Confirmation',description:'Complete your order'}]:kind==='VInvoiceTimeline'?[{label:'Invoice issued',description:'1 Oct 2026'},{label:'Payment due',description:'30 Oct 2026'},{label:'Overdue',description:'6 Nov 2026'}]:[{label:'Deposit',price:250,description:'Due today'},{label:'First instalment',price:375,description:'15 Nov 2026'},{label:'Final instalment',price:375,description:'15 Dec 2026'}])" :key="i"><span class="vx-commerce-step">{{i+1}}</span><span class="vx-commerce-flex"><strong>{{r.label}}</strong><small>{{r.description}}</small></span><strong v-if="'price' in r && r.price">{{money(r.price)}}</strong></li></ol></template>
 <template v-else-if="kind==='VPaymentMethodSelector'"><h3>{{name}}</h3><button v-for="(r,i) in [{id:'visa',label:'Visa •••• 4242',description:'Expires 12/2028'},{id:'mastercard',label:'Mastercard •••• 8888',description:'Expires 08/2029'},{id:'paypal',label:'PayPal',description:'Digital wallet'}]" :key="r.id" class="vx-commerce-choice" @click="method=r.id;emit('select',r.id)"><span>{{method===r.id?'🔘':'◯'}}</span><span class="vx-commerce-item-icon"><VIcon :name="i===2?'wallet':'credit-card'"/></span><span class="vx-commerce-flex"><strong>{{r.label}}</strong><small>{{r.description}}</small></span></button></template>
 <template v-else-if="kind==='VPaymentMethodForm'"><h3>{{name}}</h3><div class="vx-commerce-switch"><button :class="{active:method==='card'}" @click="method='card'">Card</button><button :class="{active:method==='bank'}" @click="method='bank'">Bank</button></div><div class="vx-commerce-form"><label>Card number<input placeholder="4242 4242 4242 4242" autocomplete="cc-number"/></label><div class="vx-commerce-inline"><label>Expiry<input placeholder="MM / YY" autocomplete="cc-exp"/></label><label>CVC<input placeholder="CVC" autocomplete="cc-csc"/></label></div><label>Name on card<input placeholder="Alex Morgan" autocomplete="cc-name"/></label><small>UI demonstration only. Production card fields must be hosted by a PCI-compliant payment provider.</small></div></template>
 <template v-else-if="kind==='VSecurePaymentNotice'"><div class="vx-commerce-centered"><span class="vx-commerce-security"><VIcon name="shield-check" :size="30"/></span><h3>{{name}}</h3><p class="vx-commerce-muted">Payments are processed securely. Card details are handled by your payment provider.</p><div class="vx-commerce-chip">Secure checkout</div></div></template>
 <template v-else-if="kind==='VCheckoutSummary'||kind==='VInvoiceLineItems'||kind==='VFeeBreakdown'"><h3>{{name}}</h3><div v-for="r in rows" :key="r.id" class="vx-commerce-line"><span class="vx-commerce-item-icon"><VIcon :name="r.icon||'package'"/></span><span class="vx-commerce-flex"><strong>{{r.label}}</strong><small>{{r.description}}</small></span><strong>{{money((r.price||0)*(r.quantity||1))}}</strong></div><div class="vx-commerce-totals"><div><span>Subtotal</span><span>{{money(sum)}}</span></div><div><span>{{kind==='VFeeBreakdown'?'Processing fee':'Discount'}}</span><span :class="{'vx-commerce-success':kind!=='VFeeBreakdown'}">{{kind==='VFeeBreakdown'?money(sum*.029):money(-(discount||50))}}</span></div><div><span>Tax</span><span>{{money(tax||51)}}</span></div><div class="vx-commerce-total"><strong>{{kind==='VFeeBreakdown'?'Net amount':'Total'}}</strong><strong>{{money(sum-(discount||50)+(tax||51))}}</strong></div></div><button v-if="kind==='VCheckoutSummary'" class="vx-commerce-primary" @click="emit('action','checkout')">Continue to payment</button></template>
 <template v-else-if="kind==='VPaymentStatus'"><h3>{{name}}</h3><div v-for="(r,i) in [{label:'Paid',icon:'check-circle',description:'Payment completed'},{label:'Processing',icon:'clock',description:'Your payment is processing'},{label:'Failed',icon:'circle-x',description:'Payment failed'},{label:'Refunded',icon:'refresh-cw',description:'Refund completed'}]" :key="i" class="vx-commerce-line"><span class="vx-commerce-status" :class="r.label.toLowerCase()"><VIcon :name="r.icon"/></span><span class="vx-commerce-flex"><strong>{{r.label}}</strong><small>{{r.description}}</small></span><strong>{{money(amount??450)}}</strong></div></template>
 <template v-else-if="kind==='VPaymentConfirmation'"><div class="vx-commerce-centered"><span class="vx-commerce-security success"><VIcon name="check" :size="30"/></span><h3>{{name}}</h3><p class="vx-commerce-muted">Your payment of {{money(amount??488.25)}} has been processed.</p><div class="vx-commerce-total"><span>Transaction ID</span><strong>txn_01H8X4…</strong></div><button class="vx-commerce-primary" @click="emit('action','receipt')">View receipt</button></div></template>
 <template v-else-if="kind==='VInvoiceCard'"><div class="vx-commerce-line"><span class="vx-commerce-item-icon"><VIcon name="file-text"/></span><span class="vx-commerce-flex"><strong>{{name}}</strong><small>Due 30 Oct 2026</small></span><span class="vx-commerce-chip">Unpaid</span></div><strong class="vx-commerce-value">{{money(amount??450)}}</strong><p class="vx-commerce-muted">Amount due</p><div class="vx-commerce-inline"><button @click="emit('action','view')">View invoice</button><button class="vx-commerce-primary" @click="emit('action','pay')">Pay now</button></div></template>
 <template v-else-if="kind==='VReceiptPreview'"><div class="vx-commerce-receipt"><h3>Virexen</h3><p>Payment receipt · #REC-2026-0084</p><div class="vx-commerce-total"><span>Amount paid</span><strong>{{money(amount??488.25)}}</strong></div><div class="vx-commerce-total"><span>Payment method</span><span>Visa •••• 4242</span></div><button @click="emit('action','download')">Download receipt</button></div></template>
 <template v-else-if="kind==='VSubscriptionCard'"><div class="vx-commerce-line"><span class="vx-commerce-item-icon"><VIcon name="layers"/></span><span class="vx-commerce-flex"><strong>{{name}}</strong><small>Renews 12 Nov 2026</small></span><span class="vx-commerce-chip">Active</span></div><strong class="vx-commerce-value">{{money(amount??29)}}<small>/ month</small></strong><button @click="emit('action','manage')">Manage plan</button></template>
 <template v-else-if="kind==='VPlanChangeSummary'"><h3>{{name}}</h3><div class="vx-commerce-line"><span class="vx-commerce-flex">Current plan: Growth</span><strong>{{money(29)}} /mo</strong></div><div class="vx-commerce-line"><span class="vx-commerce-flex">New plan: Enterprise</span><strong>{{money(89)}} /mo</strong></div><p class="vx-commerce-success">You'll get more features when you upgrade.</p><button class="vx-commerce-primary" @click="emit('action','upgrade')">Upgrade now</button></template>
 <template v-else-if="kind==='VRenewalNotice'||kind==='VOverdueNotice'"><div class="vx-commerce-notice" :class="kind==='VOverdueNotice'?'overdue':'renewal'"><VIcon :name="kind==='VOverdueNotice'?'alert-triangle':'calendar-days'" :size="26"/><div><h3>{{name}}</h3><p>{{kind==='VOverdueNotice'?'This invoice was due 6 days ago.':'Your plan renews on 12 Nov 2026.'}}</p><strong v-if="kind==='VOverdueNotice'">{{money(amount??450)}} due</strong></div></div><button @click="emit('action',kind==='VOverdueNotice'?'pay':'manage')">{{kind==='VOverdueNotice'?'Pay now':'Manage subscription'}}</button></template>
 <template v-else-if="kind==='VTransactionList'"><h3>{{name}}</h3><div v-for="(r,i) in [{label:'Payment',date:'12 Oct 2026',price:488.25,status:'Paid'},{label:'Refund',date:'11 Oct 2026',price:-100,status:'Refunded'},{label:'Payment',date:'15 Sep 2026',price:250,status:'Paid'}]" :key="i" class="vx-commerce-line"><small>{{r.date}}</small><span class="vx-commerce-flex">{{r.label}}</span><strong>{{money(r.price)}}</strong><span class="vx-commerce-chip">{{r.status}}</span></div></template>
 <template v-else-if="kind==='VTransactionDetails'||kind==='VRefundSummary'||kind==='VAccountBalance'"><h3>{{name}}</h3><div v-for="r in kind==='VAccountBalance'?[{label:'Account balance',value:1250},{label:'Available for payout',value:1000},{label:'On hold',value:250}]:kind==='VRefundSummary'?[{label:'Refund requested',value:-100},{label:'Refunded',value:-100}]:[{label:'Amount',value:488.25},{label:'Fees',value:-13.25},{label:'Net amount',value:475}]" :key="r.label" class="vx-commerce-total"><span>{{r.label}}</span><strong>{{money(r.value)}}</strong></div><button @click="emit('action','details')">View details</button></template>
</div></template>
<style src="./commerce-widgets.css"></style>
